        v=[float(b) for a,b in x['values']]
        out.append({'m':{k:x['metric'][k] for k in x['metric'] if k in('http_route','http_url')},'n':len(v),
                    'min':min(v),'max':max(v),'nan':sum(1 for z in v if z!=z)})
      print(json.dumps({'w':wn,'s':s,'ten':ten,'dt':round(time.time()-t0,3),'chuoi':out}))
    except Exception as ex:
